type StateUtilisationStub struct {
	*stub.MethodStub[StateUtilisationCall]

	fn       func(shard.NodeID, string) (float64, bool)
	fallback *StateUtilisationReturn
}

// StateUtilisationReturn contains the fixed results of Utilisation.
type StateUtilisationReturn struct {
	Result0 float64
	Result1 bool
}

// Returns sets the results of every call of Utilisation. A function takes
// precedence over them.
func (s *StateUtilisationStub) Returns(result0 float64, result1 bool) *StateUtilisationStub {
	s.fallback = &StateUtilisationReturn{Result0: result0, Result1: result1}
	return s
}

// Func sets the function that computes the results of Utilisation from its
// arguments.
func (s *StateUtilisationStub) Func(fn func(shard.NodeID, string) (float64, bool)) *StateUtilisationStub {
	s.fn = fn
	return s
}

