// The reference to stub.CompatV1 fails the build against another major
// version of the runtime of doubles.
var _ = stub.CompatV1

// StateStubOption configures a [StateStub] at its construction.
type StateStubOption func(*StateStub)

// StateStubStrict returns the option that makes an unconfigured method
// fail the test instead of returning its zero value.
func StateStubStrict() StateStubOption {
	return func(s *StateStub) { s.strict = true }
}

// StateStubDelegateTo returns the option that passes each call to impl.
// impl has the methods of State. Both a pointer to a State and a second
// double have them. The double still records the call.
func StateStubDelegateTo(impl interface {
	Shards() []shard.ID
	Shard(id shard.ID) (partition.Shard, bool)
	Replicas(id shard.ID) []shard.Replica
	ReplicasAt(i int) []shard.Replica
	Initial(id shard.ID) []shard.Replica
	InitialAt(i int) []shard.Replica
	InFlight(id shard.ID) (placement.InFlight, bool)
	ShardLoad(id shard.ID) shard.Load
	Desired() int
	Max(r shard.Role) int
	Nodes() []shard.NodeID
	Node(n shard.NodeID) (shard.Node, bool)
	Draining(n shard.NodeID) bool
	OnNode(n shard.NodeID) []shard.ID
	RoleCount(n shard.NodeID, r shard.Role) int
	RoleTotal(r shard.Role) int
	NodeLoad(n shard.NodeID) shard.Load
	PeakLoad(n shard.NodeID) shard.Load
	PeakCounts(n shard.NodeID, id shard.ID) bool
	PeakCount(n shard.NodeID) int
	PeakRoleCount(n shard.NodeID, r shard.Role) int
	Metrics() []placement.Metric
	Capacity(n shard.NodeID, metric string) (float64, bool)
	Utilisation(n shard.NodeID, metric string) (float64, bool)
	UtilisationSum(metric string) (float64, int)
	TotalLoad(metric string) float64
	Labelled(t tag.Tag, n shard.NodeID) int
	LabelledNodes(t tag.Tag) int
	Moved() int
	MovedNode(n shard.NodeID) int
	MovedShard(id shard.ID) int
	Apply(m placement.Move) error
},
) StateStubOption {
	return func(s *StateStub) {
		s.ShardsStub.Func(impl.Shards)
		s.ShardStub.Func(impl.Shard)
		s.ReplicasStub.Func(impl.Replicas)
		s.ReplicasAtStub.Func(impl.ReplicasAt)
		s.InitialStub.Func(impl.Initial)
		s.InitialAtStub.Func(impl.InitialAt)
		s.InFlightStub.Func(impl.InFlight)
		s.ShardLoadStub.Func(impl.ShardLoad)
		s.DesiredStub.Func(impl.Desired)
		s.MaxStub.Func(impl.Max)
		s.NodesStub.Func(impl.Nodes)
		s.NodeStub.Func(impl.Node)
		s.DrainingStub.Func(impl.Draining)
		s.OnNodeStub.Func(impl.OnNode)
		s.RoleCountStub.Func(impl.RoleCount)
		s.RoleTotalStub.Func(impl.RoleTotal)
		s.NodeLoadStub.Func(impl.NodeLoad)
		s.PeakLoadStub.Func(impl.PeakLoad)
		s.PeakCountsStub.Func(impl.PeakCounts)
		s.PeakCountStub.Func(impl.PeakCount)
		s.PeakRoleCountStub.Func(impl.PeakRoleCount)
		s.MetricsStub.Func(impl.Metrics)
		s.CapacityStub.Func(impl.Capacity)
		s.UtilisationStub.Func(impl.Utilisation)
		s.UtilisationSumStub.Func(impl.UtilisationSum)
		s.TotalLoadStub.Func(impl.TotalLoad)
		s.LabelledStub.Func(impl.Labelled)
		s.LabelledNodesStub.Func(impl.LabelledNodes)
		s.MovedStub.Func(impl.Moved)
		s.MovedNodeStub.Func(impl.MovedNode)
		s.MovedShardStub.Func(impl.MovedShard)
		s.ApplyStub.Func(impl.Apply)
	}
}

// StateStubWithClock returns the option that sets the clock of the double
// to clk. The double takes the latency, the windows of the faults and the
// instants of the calls from clk. A latency on a controlled clock costs no
// real time.
func StateStubWithClock(clk assert.Clock) StateStubOption {
	return func(s *StateStub) { s.group.SetClock(clk) }
}

// StateStubWithRandSource returns the option that sets the random source
// of the probabilistic faults to src. A seeded source repeats the faults
// of a run.
func StateStubWithRandSource(src rand.Source) StateStubOption {
	return func(s *StateStub) { s.group.SetRandSource(src) }
}

// StateStubBenchMode returns the option that turns the recording of calls
// off. The methods still return their results.
func StateStubBenchMode() StateStubOption {
	return func(s *StateStub) { s.group.BenchMode() }
}

// StateStubWithLatency returns the option that makes every method sleep d
// before it returns. Without StateStubWithClock, d passes in real time.
func StateStubWithLatency(d time.Duration) StateStubOption {
	return func(s *StateStub) { s.group.SetLatency(d) }
}

// StateStubFailing returns the option that arms err on each method that
// can fail. Each call of such a method then fails with err.
func StateStubFailing(err error) StateStubOption {
	return func(s *StateStub) {
		s.ApplyStub.Faults(err, 1)
	}
}

